        IntrinsicGas intrinsicGas = IntrinsicGasCalculator.Calculate(transaction, releaseSpec);
        return transaction.GasLimit < intrinsicGas.MinimalGas
            ? TxErrorMessages.IntrinsicGasTooLow
            : ValidationResult.Success;
