    10→[assembly: InternalsVisibleTo("Nethermind.TxPool.Test")]
    11→
    12→namespace Nethermind.TxPool
    13→{
    14→    public static class TransactionExtensions
    15→    {
    16→        private static readonly long MaxSizeOfTxForBroadcast = 4.KiB(); //4KB, as in Geth https://github.com/ethereum/go-ethereum/pull/27618
    17→        private static readonly ITransactionSizeCalculator _transactionSizeCalculator = new NetworkTransactionSizeCalculator(TxDecoder.Instance);
    18→
    19→        public static int GetLength(this Transaction tx, bool shouldCountBlobs = true)
    20→        {
    21→            return tx.GetLength(_transactionSizeCalculator, shouldCountBlobs);
    22→        }
    23→
    24→        public static bool CanPayBaseFee(this Transaction tx, UInt256 currentBaseFee) => tx.MaxFeePerGas >= currentBaseFee;
    25→
    26→        public static bool CanPayForBlobGas(this Transaction tx, UInt256 currentPricePerBlobGas) => !tx.SupportsBlobs || tx.MaxFeePerBlobGas >= currentPricePerBlobGas;
    27→
    28→        public static bool CanBeBroadcast(this Transaction tx) => !tx.SupportsBlobs && tx.GetLength() <= MaxSizeOfTxForBroadcast;
    29→
    30→        internal static UInt256 CalculateGasPrice(this Transaction tx, bool eip1559Enabled, in UInt256 baseFee)
    31→        {
    32→            if (eip1559Enabled && tx.Supports1559)
    33→            {
    34→                if (tx.GasLimit > 0)
    35→                {
    36→                    return tx.CalculateEffectiveGasPrice(eip1559Enabled, baseFee);
    37→                }
    38→
    39→                return 0;
    40→            }
    41→
    42→            return tx.GasPrice;
    43→        }
    44→
    45→        internal static UInt256 CalculateAffordableGasPrice(this Transaction tx, bool eip1559Enabled, in UInt256 baseFee, in UInt256 balance)
    46→        {
    47→            if (eip1559Enabled && tx.Supports1559)
    48→            {
    49→                if (balance > tx.ValueRef && tx.GasLimit > 0)
    50→                {
    51→                    UInt256 effectiveGasPrice = tx.CalculateEffectiveGasPrice(eip1559Enabled, baseFee);
    52→                    effectiveGasPrice.Multiply((UInt256)tx.GasLimit, out UInt256 gasCost);
    53→
    54→                    if (balance >= tx.ValueRef + gasCost)
    55→                    {
    56→                        return effectiveGasPrice;
    57→                    }
    58→
    59→                    UInt256 balanceAvailableForFeePayment = balance - tx.ValueRef;
    60→                    balanceAvailableForFeePayment.Divide((UInt256)tx.GasLimit, out UInt256 payablePricePerGasUnit);
    61→                    return payablePricePerGasUnit;
    62→                }
    63→
    64→                return 0;
    65→            }
    66→
    67→            return balance <= tx.ValueRef ? default : tx.GasPrice;
    68→        }
    69→
    70→        internal static bool CheckForNotEnoughBalance(this Transaction tx, UInt256 currentCost, UInt256 balance, out UInt256 cumulativeCost)
    71→            => tx.IsOverflowWhenAddingTxCostToCumulative(currentCost, out cumulativeCost) || balance < cumulativeCost;
    72→
    73→        internal static bool IsOverflowWhenAddingTxCostToCumulative(this Transaction tx, UInt256 currentCost, out UInt256 cumulativeCost)
    74→        {
    75→            bool overflow = false;
    76→
    77→            overflow |= UInt256.MultiplyOverflow(tx.MaxFeePerGas, (UInt256)tx.GasLimit, out UInt256 maxTxCost);
    78→            overflow |= UInt256.AddOverflow(currentCost, maxTxCost, out cumulativeCost);
    79→            overflow |= UInt256.AddOverflow(in cumulativeCost, in tx.ValueRef, out cumulativeCost);
    80→
    81→            if (tx.SupportsBlobs)
    82→            {
    83→                // if tx.SupportsBlobs and has BlobVersionedHashes = null, it will throw on earlier step of validation, in TxValidator
    84→                overflow |= UInt256.MultiplyOverflow(Eip4844Constants.GasPerBlob, (UInt256)tx.BlobVersionedHashes!.Length, out UInt256 blobGas);
    85→                overflow |= UInt256.MultiplyOverflow(blobGas, tx.MaxFeePerBlobGas ?? UInt256.MaxValue, out UInt256 blobGasCost);
    86→                overflow |= UInt256.AddOverflow(cumulativeCost, blobGasCost, out cumulativeCost);
    87→            }
    88→
    89→            return overflow;
    90→        }
    91→
    92→        internal static bool IsOverflowInTxCostAndValue(this Transaction tx, out UInt256 txCost)
    93→            => IsOverflowWhenAddingTxCostToCumulative(tx, UInt256.Zero, out txCost);
